<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/commerce_v1230.php';$token=preg_replace('/[^a-f0-9]/','',(string)($_GET['token']??$_POST['token']??''));$o=sk1230_order(0,$token);if(!$o||!sk1230_can_view_order($o)){http_response_code(404);exit('Order not found.');}$msg='';$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();$a=(string)($_POST['action']??'');if($a==='return'){sk1230_return_request((int)$o['id'],(string)($_POST['reason']??''),(string)($_POST['details']??''));$msg='Return request submitted.';}elseif($a==='dispute'){sk1230_dispute_request((int)$o['id'],(string)($_POST['subject']??''),(string)($_POST['details']??''));$msg='Dispute submitted to ShahkotPK support.';}}}catch(Throwable $e){$err=$e->getMessage();}$o=sk1230_order(0,$token);$s=sk1230_settings();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=sk1230_h($o['order_no'])?> — Order Tracking</title><link rel="stylesheet" href="/assets/commerce-v1230.css?v=1230"></head><body><main class="co1230"><header class="co-top"><div><a class="co-brand" href="/my-orders-v1230.php">← My Orders</a><div class="co-kicker">LIVE ORDER JOURNEY</div><h1><?=sk1230_h($o['order_no'])?></h1><p>Placed <?=sk1230_h($o['created_at'])?> · <?=sk1230_money($o['grand_total'])?></p></div><div class="co-actions"><button onclick="window.print()">Print Receipt</button><span class="status <?=sk1230_h($o['status'])?>"><?=sk1230_h(str_replace('_',' ',$o['status']))?></span></div></header><?php if(isset($_GET['placed'])):?><div class="notice ok">Order placed successfully. Keep this page or order number for tracking.</div><?php endif;?><?php if($msg):?><div class="notice ok"><?=sk1230_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice bad"><?=sk1230_h($err)?></div><?php endif;?><div class="grid"><section><div class="panel"><div class="panel-head"><div><h2>Seller fulfillment</h2><p>Each business can prepare and deliver its part independently.</p></div></div><?php foreach($o['groups'] as $g):?><article class="seller"><div class="seller-head"><div><b><?=sk1230_h($g['business_name']?:'Business')?></b><span class="status <?=sk1230_h($g['status'])?>"><?=sk1230_h(str_replace('_',' ',$g['status']))?></span></div><strong><?=sk1230_money($g['total'])?></strong></div><div class="seller-items"><?php foreach($g['items'] as $it):?><div class="seller-item"><span><?=(int)$it['qty']?> × <?=sk1230_h($it['product_name'])?></span><b><?=sk1230_money($it['line_total'])?></b></div><?php endforeach;?></div><?php if($g['delivery']):?><div class="job"><b>Rider: <?=sk1230_h($g['delivery']['rider_name']?:'Assigned rider')?></b><p><?=sk1230_h($g['delivery']['vehicle_type'])?> <?=sk1230_h($g['delivery']['vehicle_no'])?></p><?php if($g['delivery']['rider_phone']):?><a class="btn ghost" href="tel:<?=sk1230_h($g['delivery']['rider_phone'])?>">Call Rider</a><?php endif;?><?php if((int)$g['delivery']['eta_minutes']>0):?><span class="pill">ETA ~<?=(int)$g['delivery']['eta_minutes']?> min</span><?php endif;?><?php if($g['delivery']['location_updated_at']):?><small>Location/status updated <?=sk1230_h($g['delivery']['location_updated_at'])?></small><?php endif;?></div><?php endif;?></article><?php endforeach;?></div><div class="panel"><h2>Order details</h2><div class="summary-line"><span>Products</span><b><?=sk1230_money($o['subtotal'])?></b></div><div class="summary-line"><span>Delivery</span><b><?=sk1230_money($o['delivery_fee'])?></b></div><?php if((float)$o['discount_total']>0):?><div class="summary-line"><span>Discount</span><b>-<?=sk1230_money($o['discount_total'])?></b></div><?php endif;?><?php if((float)$o['wallet_used']>0):?><div class="summary-line"><span>Wallet paid</span><b><?=sk1230_money($o['wallet_used'])?></b></div><?php endif;?><div class="summary-line total"><span>Total</span><b><?=sk1230_money($o['grand_total'])?></b></div><p><b>Payment:</b> <?=sk1230_h(strtoupper($o['payment_method']))?> · <?=sk1230_h($o['payment_status'])?></p><p><b>Fulfillment:</b> <?=sk1230_h($o['fulfillment_type'])?><?php if($o['scheduled_for']):?> · Scheduled <?=sk1230_h($o['scheduled_for'])?><?php endif;?></p><?php if($o['address_text']):?><p><b>Address:</b> <?=sk1230_h($o['address_text'])?>, <?=sk1230_h($o['area'])?></p><?php endif;?></div></section><aside><div class="panel"><h2>Order timeline</h2><div class="timeline"><?php foreach($o['timeline'] as $t):?><div class="timeline-item"><b><?=sk1230_h(ucwords(str_replace('_',' ',$t['status'])))?></b><?php if($t['note']):?><p><?=sk1230_h($t['note'])?></p><?php endif;?><small><?=sk1230_h($t['created_at'])?></small></div><?php endforeach;?></div></div><?php if($s['returns_enabled']&&$o['status']==='delivered'):?><div class="panel"><h3>Request Return</h3><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=sk1230_h(csrf_token())?>"><input type="hidden" name="token" value="<?=sk1230_h($token)?>"><input type="hidden" name="action" value="return"><label class="wide">Reason<select name="reason"><option>Wrong / damaged item</option><option>Item not as expected</option><option>Missing item</option><option>Other</option></select></label><label class="wide">Details<textarea name="details" rows="3"></textarea></label><button class="btn ghost wide">Submit Return Request</button></form></div><?php endif;?><?php if($s['disputes_enabled']):?><div class="panel"><h3>Need ShahkotPK Support?</h3><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=sk1230_h(csrf_token())?>"><input type="hidden" name="token" value="<?=sk1230_h($token)?>"><input type="hidden" name="action" value="dispute"><label class="wide">Subject<input name="subject" required maxlength="190"></label><label class="wide">Details<textarea name="details" required rows="3"></textarea></label><button class="btn ghost wide">Open Dispute</button></form></div><?php endif;?></aside></div></main></body></html>
